 19→// TaskHookInput represents the JSON input from PreToolUse[Task] hook
 20→type TaskHookInput struct {
 21→	SessionID      string          `json:"session_id"`
 22→	TranscriptPath string          `json:"transcript_path"`
 23→	ToolUseID      string          `json:"tool_use_id"`
 24→	ToolInput      json.RawMessage `json:"tool_input"`
 25→}
