 27→// postTaskHookInputRaw is the raw JSON structure from PostToolUse[Task] hook
 28→type postTaskHookInputRaw struct {
 29→	SessionID      string          `json:"session_id"`
 30→	TranscriptPath string          `json:"transcript_path"`
 31→	ToolUseID      string          `json:"tool_use_id"`
 32→	ToolInput      json.RawMessage `json:"tool_input"`
 33→	ToolResponse   struct {
 34→		AgentID string `json:"agentId"`
 35→	} `json:"tool_response"`
 36→}
