 38→// PostTaskHookInput represents the parsed input from PostToolUse[Task] hook
 39→type PostTaskHookInput struct {
 40→	TaskHookInput
 41→
 42→	AgentID   string          // Extracted from tool_response.agentId
 43→	ToolInput json.RawMessage // Raw tool input for reference
 44→}
