 46→// parseTaskHookInput parses PreToolUse[Task] hook input from reader
 47→func parseTaskHookInput(r io.Reader) (*TaskHookInput, error) {
 48→	data, err := io.ReadAll(r)
 49→	if err != nil {
 50→		return nil, fmt.Errorf("failed to read input: %w", err)
 51→	}
 52→
 53→	if len(data) == 0 {
 54→		return nil, errors.New("empty input")
 55→	}
 56→
 57→	var input TaskHookInput
 58→	if err := json.Unmarshal(data, &input); err != nil {
 59→		return nil, fmt.Errorf("failed to parse JSON: %w", err)
 60→	}
 61→
 62→	return &input, nil
 63→}
