 65→// parsePostTaskHookInput parses PostToolUse[Task] hook input from reader
 66→func parsePostTaskHookInput(r io.Reader) (*PostTaskHookInput, error) {
 67→	data, err := io.ReadAll(r)
 68→	if err != nil {
 69→		return nil, fmt.Errorf("failed to read input: %w", err)
 70→	}
 71→
 72→	if len(data) == 0 {
