152→// todoWriteToolInput represents the tool_input structure for the TodoWrite tool.
153→// Used to extract the todos array which is then passed to strategy.ExtractInProgressTodo.
154→type todoWriteToolInput struct {
155→	Todos json.RawMessage `json:"todos"`
156→}
