  9→func TestParsePreTaskHookInput(t *testing.T) {
 10→	tests := []struct {
 11→		name    string
 12→		input   string
 13→		want    *TaskHookInput
 14→		wantErr bool
 15→	}{
 16→		{
 17→			name:  "valid input",
 18→			input: `{"session_id":"abc123","transcript_path":"/path/to/transcript.jsonl","tool_use_id":"tool_xyz"}`,
 19→			want: &TaskHookInput{
 20→				SessionID:      "abc123",
 21→				TranscriptPath: "/path/to/transcript.jsonl",
 22→				ToolUseID:      "tool_xyz",
 23→			},
 24→			wantErr: false,
 25→		},
 26→		{
 27→			name:    "empty input",
 28→			input:   "",
 29→			want:    nil,
 30→			wantErr: true,
 31→		},
 32→		{
 33→			name:    "invalid json",
 34→			input:   "not json",
 35→			want:    nil,
 36→			wantErr: true,
 37→		},
 38→		{
 39→			name:  "missing fields uses defaults",
 40→			input: `{"session_id":"abc123"}`,
 41→			want: &TaskHookInput{
 42→				SessionID:      "abc123",
 43→				TranscriptPath: "",
 44→				ToolUseID:      "",
 45→			},
 46→			wantErr: false,
 47→		},
 48→	}
 49→
 50→	for _, tt := range tests {
 51→		t.Run(tt.name, func(t *testing.T) {
 52→			reader := strings.NewReader(tt.input)
 53→			got, err := parseTaskHookInput(reader)
 54→
 55→			if (err != nil) != tt.wantErr {
 56→				t.Errorf("parseTaskHookInput() error = %v, wantErr %v", err, tt.wantErr)
 57→				return
 58→			}
 59→
 60→			if tt.want != nil {
 61→				if got.SessionID != tt.want.SessionID {
 62→					t.Errorf("SessionID = %v, want %v", got.SessionID, tt.want.SessionID)
 63→				}
 64→				if got.TranscriptPath != tt.want.TranscriptPath {
 65→					t.Errorf("TranscriptPath = %v, want %v", got.TranscriptPath, tt.want.TranscriptPath)
 66→				}
 67→				if got.ToolUseID != tt.want.ToolUseID {
 68→					t.Errorf("ToolUseID = %v, want %v", got.ToolUseID, tt.want.ToolUseID)
 69→				}
 70→			}
 71→		})
 72→	}
 73→}
